-- MAJY Academy schema. Apply with: npx wrangler d1 migrations apply MAJY_Academy_DB --remote
CREATE TABLE IF NOT EXISTS academy_lessons (
  day_number INTEGER PRIMARY KEY CHECK (day_number BETWEEN 1 AND 7),
  publish_date TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  subtitle TEXT NOT NULL,
  content_json TEXT NOT NULL,
  quiz_json TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','published')),
  published_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_academy_lessons_status_date
ON academy_lessons(status, publish_date);

-- Seven-day foundation course seed data (3–9 November 2026).
INSERT OR IGNORE INTO academy_lessons (day_number, publish_date, title, subtitle, content_json, quiz_json, status) VALUES (1, '2026-11-03', 'Stock Market Fundamentals', 'Understand the marketplace before trying to trade it.', '{"day":1,"date":"2026-11-03","title":"Stock Market Fundamentals","subtitle":"Understand the marketplace before trying to trade it.","objectives":["Explain what a share, exchange, index and order book are.","Distinguish market, limit and stop orders.","Understand liquidity, spread and the difference between intraday and delivery trading."],"sections":[{"heading":"1. What is a share?","body":"A share represents a small ownership interest in a company. When you buy a share, you participate in the company''s fortunes, but the market price can move up or down independently of the company''s long-term value."},{"heading":"2. What does the exchange do?","body":"An exchange such as NSE provides an organised marketplace where buyers'' and sellers'' orders can meet. A broker gives you access to that marketplace. The exchange is not the person taking the opposite side of every trade."},{"heading":"3. Indices: the market''s temperature","body":"Nifty 50 and Sensex are baskets of selected companies. They are useful summaries, not a complete picture of every stock. A stock can rise while the index falls, and vice versa."},{"heading":"4. The order book","body":"The bid side shows prices buyers are willing to pay; the ask/offer side shows prices sellers are willing to accept. The best bid and best ask form the spread. A narrow spread and substantial depth usually make execution easier, but liquidity can disappear during fast markets."},{"heading":"5. Order types","body":"A market order prioritises execution, not price. A limit order sets the worst price you are willing to accept, but may not execute. A stop order is triggered at a specified level; the final execution price can differ in a fast market."},{"heading":"6. Trading styles","body":"Intraday trades are opened and closed within the same trading day. Swing trades are held across multiple sessions. Investing generally has a longer horizon. The time horizon changes the tools, costs and risks."}],"analogy":"Think of the stock exchange as a busy vegetable market. Buyers announce the price they will pay, sellers announce the price they want, and a deal happens when the prices meet. A market order says “get me a deal now”; a limit order says “only deal at this price or better.”","mnemonic":"B-A-S-I-C: **B**id, **A**sk, **S**pread, **I**ndex, **C**harts. Know the marketplace before studying the chart.","example":"Suppose a liquid NSE share shows best bid ₹499.90 and best ask ₹500.00. The spread is ₹0.10. A market buy may execute near the ask, but a large order or a fast market can produce a worse average price.","takeaways":["A share is ownership; an exchange matches orders.","Bid = buyers; ask = sellers; spread = ask minus bid.","Market orders do not guarantee a particular price.","Liquidity and transaction costs matter, especially intraday."]}', '[{"id":"d1q1","question":"What does the bid side of an order book represent?","options":["Prices buyers are willing to pay","Prices sellers demand","Yesterday''s closing prices","The day''s traded volume"],"answer":0,"explanation":"The bid side contains buyers'' prices; the ask side contains sellers'' offers."},{"id":"d1q2","question":"What is the spread?","options":["The day''s high minus low","Best ask minus best bid","The broker''s annual fee","The difference between Nifty and Sensex"],"answer":1,"explanation":"The spread is the best ask price minus the best bid price."},{"id":"d1q3","question":"Which order type specifies a maximum price for a buy?","options":["Market order","Limit order","Stop market order","After-market order"],"answer":1,"explanation":"A buy limit sets the maximum price you are willing to pay; execution is not guaranteed."}]', 'scheduled');
INSERT OR IGNORE INTO academy_lessons (day_number, publish_date, title, subtitle, content_json, quiz_json, status) VALUES (2, '2026-11-04', 'Candlesticks and Price Action', 'Read the story of buyers and sellers in each candle.', '{"day":2,"date":"2026-11-04","title":"Candlesticks and Price Action","subtitle":"Read the story of buyers and sellers in each candle.","objectives":["Read OHLC values and candle anatomy.","Interpret body, wick and closing position without treating patterns as guarantees.","Identify basic trend structure and support/resistance zones."],"sections":[{"heading":"1. OHLC in one candle","body":"Every candle summarises Open, High, Low and Close for a chosen interval. A green/up candle closes above its open; a red/down candle closes below its open. The candle does not reveal every trade that happened inside the interval."},{"heading":"2. Body and wicks","body":"The body is the distance between open and close. The upper wick reaches the high; the lower wick reaches the low. A long body shows a large net move during that interval. A long wick shows price travelled away from the close before the interval ended."},{"heading":"3. Context beats candle names","body":"A hammer-like candle near a well-tested support zone after a decline may be worth investigating. The same shape in the middle of a noisy range may mean very little. Wait for context and confirmation; no single candle predicts the future."},{"heading":"4. Market structure","body":"An uptrend often forms higher highs and higher lows. A downtrend often forms lower highs and lower lows. Sideways markets move between zones without a sustained sequence. Structure depends on timeframe."},{"heading":"5. Support and resistance","body":"Support and resistance are zones where price previously attracted buying or selling. They are not precise walls. A level can break, fail, or later switch roles."}],"analogy":"A candle is like a one-minute sports scoreboard: it tells you the starting score, the highest and lowest score reached, and the final score. It does not show every pass or every player decision.","mnemonic":"OHLC = **O**pen, **H**igh, **L**ow, **C**lose. For candle reading ask **B-W-C**: Body, Wicks, Context.","example":"A 15-minute candle opens at ₹250, reaches ₹254, falls to ₹248 and closes at ₹253. It has a ₹3 bullish body, a ₹1 upper wick and a ₹2 lower wick. Buyers finished the interval in control, but the next candle must confirm whether that strength continues.","takeaways":["OHLC describes one interval, not the whole market.","Read body and wicks together with location and trend.","Support/resistance are zones, not guarantees.","Always specify the chart timeframe."]}', '[{"id":"d2q1","question":"What does OHLC stand for?","options":["Open, High, Low, Close","Order, Hold, Limit, Cancel","Open, Hold, Last, Change","Offer, High, Last, Close"],"answer":0,"explanation":"OHLC summarises the open, high, low and close of a candle interval."},{"id":"d2q2","question":"A long upper wick means:","options":["Price never moved down","Price reached higher but closed below the high","The next candle must fall","Volume was zero"],"answer":1,"explanation":"The upper wick marks the high above the candle body; it is not a guaranteed reversal signal."},{"id":"d2q3","question":"Which is the strongest way to interpret a candle pattern?","options":["By its name alone","Without a timeframe","With trend, location and confirmation","As a guaranteed prediction"],"answer":2,"explanation":"Candles need market structure and context; no pattern guarantees an outcome."}]', 'scheduled');
INSERT OR IGNORE INTO academy_lessons (day_number, publish_date, title, subtitle, content_json, quiz_json, status) VALUES (3, '2026-11-05', 'Technical Indicators', 'Use indicators as measuring instruments, not crystal balls.', '{"day":3,"date":"2026-11-05","title":"Technical Indicators","subtitle":"Use indicators as measuring instruments, not crystal balls.","objectives":["Explain moving averages, RSI, MACD, VWAP, ADX and ATR.","Know which question each indicator helps answer.","Avoid stacking several indicators that measure the same thing."],"sections":[{"heading":"1. Moving averages","body":"A moving average smooths price over a selected number of periods. Short averages react faster; long averages react slower. Crossovers can lag because they are calculated from past prices."},{"heading":"2. RSI","body":"Relative Strength Index measures the speed and magnitude of recent price changes on a 0–100 scale. Traditional 70/30 levels are reference points, not automatic sell/buy instructions. Strong trends can remain overbought or oversold."},{"heading":"3. MACD","body":"MACD compares two exponential moving averages and includes a signal line and histogram. It can help visualise momentum shifts, but it is derived from price and can lag."},{"heading":"4. VWAP","body":"Volume Weighted Average Price is the session''s average traded price weighted by volume. Intraday traders often compare price with VWAP to assess where trading is occurring relative to the session average."},{"heading":"5. ADX and ATR","body":"ADX estimates trend strength, not direction. ATR estimates typical volatility, not direction. They can help decide whether a trend filter is strong enough and how much room a stop might need."},{"heading":"6. Volume","body":"Volume tells you how many shares traded in a period. A breakout with stronger-than-usual volume may have more participation, but volume alone does not prove the move will continue."}],"analogy":"Indicators are like instruments on a vehicle dashboard. The speedometer, fuel gauge and engine temperature answer different questions. Staring at six speedometers does not make the journey safer.","mnemonic":"**T-M-V-R**: Trend (moving averages/ADX), Momentum (RSI/MACD), Value (VWAP), Range (ATR). Ask what question an indicator answers before adding it.","example":"If a stock is above a rising 20 EMA and VWAP, ADX is strengthening, and volume is above its recent average, several independent clues may support a trend-following hypothesis. They still do not guarantee a profitable entry.","takeaways":["Moving averages smooth trend; RSI/MACD describe momentum.","VWAP is a volume-weighted session reference.","ADX measures trend strength; ATR measures volatility.","Use a small set of complementary indicators."]}', '[{"id":"d3q1","question":"Which indicator is designed to estimate trend strength rather than direction?","options":["ADX","RSI","VWAP","ATR"],"answer":0,"explanation":"ADX estimates trend strength; it does not tell you whether the trend is up or down."},{"id":"d3q2","question":"VWAP is:","options":["A volume-weighted average price","A volatility forecast","A momentum oscillator","A moving stop-loss"],"answer":0,"explanation":"VWAP weights traded prices by volume over the session."},{"id":"d3q3","question":"ATR primarily measures:","options":["Direction","Volatility/range","Company valuation","Order-book depth"],"answer":1,"explanation":"ATR estimates typical price range/volatility, not direction."}]', 'scheduled');
INSERT OR IGNORE INTO academy_lessons (day_number, publish_date, title, subtitle, content_json, quiz_json, status) VALUES (4, '2026-11-06', 'Trading Strategies', 'Turn observations into rules that can be tested.', '{"day":4,"date":"2026-11-06","title":"Trading Strategies","subtitle":"Turn observations into rules that can be tested.","objectives":["Describe breakout, opening-range, trend-following and mean-reversion ideas.","Define entry, exit, stop and no-trade conditions.","Understand why a strategy needs explicit rules."],"sections":[{"heading":"1. Opening Range Breakout (ORB)","body":"Define an opening range, for example the first 15 minutes. A rule may consider a long entry only after price closes above the range high, with volume and market-context filters. The range, trigger and invalidation must be specified before testing."},{"heading":"2. Trend following","body":"A trend strategy tries to participate in persistent directional movement. It may use moving-average slope, market structure and a volatility-based stop. It will often experience small losses in sideways markets."},{"heading":"3. Mean reversion","body":"A mean-reversion strategy looks for price to move unusually far from a reference and then return. It can fail badly when a genuine trend keeps extending. A regime filter is essential."},{"heading":"4. Momentum and relative strength","body":"Momentum strategies seek instruments showing stronger movement than a benchmark or peer group. Relative strength is comparative; it is not the same as RSI."},{"heading":"5. Define the whole trade","body":"A complete rule set states the universe, timeframe, entry trigger, stop-loss, exit, position size, trading hours, filters and conditions to skip. “Buy when it looks strong” is not testable."}],"analogy":"A strategy is a recipe. “Cook something tasty” is not a recipe. You need ingredients, quantities, sequence, temperature and a rule for when it is ready.","mnemonic":"**E-S-E-F**: Entry, Stop, Exit, Filter. If one is missing, the strategy is unfinished.","example":"A hypothetical ORB rule: observe 9:15–9:30 IST; consider a long only after a 5-minute candle closes above the opening-range high; require volume above a defined baseline; place a pre-defined protective stop; exit by a stated time. This is a testable hypothesis, not a recommendation.","takeaways":["A strategy is a complete set of objective rules.","Breakouts and mean reversion behave differently across regimes.","Define no-trade conditions as carefully as entry conditions.","Backtest before risking capital."]}', '[{"id":"d4q1","question":"A complete trading strategy must define:","options":["Only an entry signal","Entry, stop, exit, filters and sizing","Only the stock name","Only the indicator settings"],"answer":1,"explanation":"A strategy must define the whole trade and when not to trade."},{"id":"d4q2","question":"Opening Range Breakout uses:","options":["The previous year''s high","A defined early-session price range","Only RSI below 30","A random entry time"],"answer":1,"explanation":"ORB defines an initial range, then tests a breakout against explicit rules."},{"id":"d4q3","question":"Mean reversion is most vulnerable when:","options":["Price is range-bound","A strong trend keeps extending","Volume is low","Markets are closed"],"answer":1,"explanation":"A persistent trend can keep moving away from the mean, causing repeated countertrend losses."}]', 'scheduled');
INSERT OR IGNORE INTO academy_lessons (day_number, publish_date, title, subtitle, content_json, quiz_json, status) VALUES (5, '2026-11-07', 'Quantitative Trading and Mathematics', 'Measure the edge, the uncertainty and the amount at risk.', '{"day":5,"date":"2026-11-07","title":"Quantitative Trading and Mathematics","subtitle":"Measure the edge, the uncertainty and the amount at risk.","objectives":["Calculate risk/reward and expectancy.","Understand win rate, average win/loss and drawdown.","Calculate position size from a fixed risk budget."],"sections":[{"heading":"1. Risk per trade","body":"Risk per trade is the amount you plan to lose if the stop is executed, before allowing for gaps, slippage or exceptional events. It is not the amount invested in the position."},{"heading":"2. Position sizing","body":"A basic formula is quantity = risk budget ÷ (entry price − stop price) for a long trade. Round down to a permitted quantity and check liquidity, lot size and costs. Real losses can exceed planned risk."},{"heading":"3. Expectancy","body":"Expectancy = (win probability × average win) − (loss probability × average loss), measured per trade before or after costs consistently. A high win rate can still lose money if average losses are much larger."},{"heading":"4. Risk/reward","body":"If planned reward is ₹600 and planned risk is ₹300, the planned reward-to-risk ratio is 2:1. This ratio alone says nothing about the probability of reaching the target."},{"heading":"5. Drawdown and sample size","body":"Drawdown measures decline from a prior equity peak. A short winning streak is not proof of an edge. Results vary; evaluate enough trades and include different market conditions."}],"analogy":"Position sizing is like choosing how much water to put in a bucket with a small hole. The size of the bucket is your exposure; the hole is your stop distance. A wider hole means you should carry less water if you want the same potential loss.","mnemonic":"**R-Q-E-D**: Risk budget, Quantity, Expectancy, Drawdown. Calculate before clicking Buy or Sell.","example":"Illustration only: account ₹2,00,000; risk budget 0.25% = ₹500. Entry ₹250 and stop ₹245 means ₹5 risk per share. Quantity = ₹500/₹5 = 100 shares, before costs and slippage. If the stop fills below ₹245, actual loss may be higher.","takeaways":["Position size depends on risk budget and stop distance.","Expectancy combines win rate with average win and loss.","Costs can turn a theoretical edge into a losing strategy.","Drawdown and losing streaks are part of trading."]}', '[{"id":"d5q1","question":"Account ₹2,00,000 and risk budget 0.25%. What is the budget?","options":["₹50","₹250","₹500","₹5,000"],"answer":2,"explanation":"0.25% × ₹2,00,000 = ₹500."},{"id":"d5q2","question":"Entry ₹250, stop ₹245, risk budget ₹500. Basic quantity?","options":["50","100","250","500"],"answer":1,"explanation":"Risk per share is ₹5; ₹500 ÷ ₹5 = 100 shares before costs/slippage."},{"id":"d5q3","question":"Expectancy depends on:","options":["Win rate only","Average win only","Win probability, average win and average loss","Number of indicators"],"answer":2,"explanation":"Expectancy combines the probability and size of wins and losses."}]', 'scheduled');
INSERT OR IGNORE INTO academy_lessons (day_number, publish_date, title, subtitle, content_json, quiz_json, status) VALUES (6, '2026-11-08', 'Algo Trading and Backtesting', 'Make the rules executable, then challenge them with history.', '{"day":6,"date":"2026-11-08","title":"Algo Trading and Backtesting","subtitle":"Make the rules executable, then challenge them with history.","objectives":["Identify the parts of an algorithmic trading system.","Explain backtesting, paper trading and walk-forward testing.","Recognise common backtest biases and execution costs."],"sections":[{"heading":"1. The algorithm pipeline","body":"A basic system receives market data, calculates features, generates a signal, checks risk limits, sends an order through a broker interface, monitors execution and records every event. Each stage needs error handling."},{"heading":"2. Backtesting","body":"A backtest applies defined rules to historical data. It is a research tool, not a forecast. Data quality, corporate actions, trading hours, order fills and costs strongly affect results."},{"heading":"3. Avoid look-ahead and survivorship bias","body":"Look-ahead bias uses information that would not have been available at the decision time. Survivorship bias tests only securities that survived to the present and ignores delisted failures. Both can make results look too good."},{"heading":"4. Overfitting","body":"If you keep tuning parameters until the historical curve looks perfect, you may be fitting noise. Keep a holdout period, limit parameter search, and prefer simpler rules with a plausible rationale."},{"heading":"5. Out-of-sample and walk-forward","body":"Develop on one period, evaluate on a separate unseen period, then repeat through walk-forward windows. Performance should be reasonably stable rather than depending on one lucky interval."},{"heading":"6. Paper trading","body":"Paper trading tests live data flow and order logic without committing real capital. It does not perfectly reproduce fills, queue position, slippage or the emotions of live trading."}],"analogy":"A backtest is like practising a driving route on a simulator. It helps reveal design flaws, but it cannot guarantee road conditions, traffic or vehicle behaviour tomorrow.","mnemonic":"**D-C-B-P**: Data, Costs, Bias, Paper-trade. Check all four before believing a backtest.","example":"A strategy that buys at the candle close cannot assume it also receives that exact closing price if the signal is only known after the candle has closed. Model the next realistically available execution price and include brokerage, taxes, spread and slippage.","takeaways":["A trading algorithm needs data, signal, risk, execution and logging.","Include realistic costs and execution assumptions.","Prevent look-ahead, survivorship bias and overfitting.","Use out-of-sample tests and paper trading before live deployment."]}', '[{"id":"d6q1","question":"Look-ahead bias occurs when:","options":["Using only old data","Using information unavailable at the decision time","Including brokerage","Testing a separate period"],"answer":1,"explanation":"Look-ahead bias leaks future information into past decisions."},{"id":"d6q2","question":"Why include slippage in a backtest?","options":["It improves the equity curve","It approximates execution price impact","It replaces risk management","It removes market risk"],"answer":1,"explanation":"Slippage can make actual fills worse than assumed prices."},{"id":"d6q3","question":"What is walk-forward testing?","options":["Optimising on all data once","Repeatedly testing on later unseen windows","Trading only on Fridays","Ignoring costs"],"answer":1,"explanation":"Walk-forward validation tests a model through sequential out-of-sample periods."}]', 'scheduled');
INSERT OR IGNORE INTO academy_lessons (day_number, publish_date, title, subtitle, content_json, quiz_json, status) VALUES (7, '2026-11-09', 'Risk Management, AI and System Design', 'Design a process that can survive being wrong.', '{"day":7,"date":"2026-11-09","title":"Risk Management, AI and System Design","subtitle":"Design a process that can survive being wrong.","objectives":["Set portfolio and daily risk controls.","Understand where machine learning may help and where it can mislead.","Sketch a safe, staged roadmap for an Indian-market algo platform."],"sections":[{"heading":"1. Risk controls come first","body":"Set limits for risk per trade, daily loss, total open exposure, number of positions and consecutive losses. Include a kill switch for data failures, repeated order rejections or unexpected positions. Limits must be enforced by the system, not just displayed."},{"heading":"2. Market regime","body":"A strategy can behave differently in trending, sideways and high-volatility conditions. Regime filters may use trend, volatility and breadth measures, but they too can be wrong or lag."},{"heading":"3. AI and machine learning","body":"Start with interpretable baselines. Logistic regression or tree-based models can estimate probabilities or rank opportunities, but only when labels, features and validation are carefully designed. More complex models do not automatically create an edge."},{"heading":"4. System architecture","body":"Separate research/backtesting, signal generation, portfolio risk, broker execution, monitoring and audit logs. Keep broker credentials secure, use least privilege, and never place API secrets in browser JavaScript or a public repository."},{"heading":"5. India-specific readiness","body":"Before live retail algo deployment, verify current SEBI, exchange and broker requirements, API permissions, order controls and applicable approvals with the broker and qualified compliance support. Rules and implementation details can change."},{"heading":"6. Staged roadmap","body":"Stage 1: learn and specify rules. Stage 2: build a research dataset and backtester. Stage 3: validate out of sample. Stage 4: paper trade and monitor. Stage 5: obtain broker/compliance readiness. Only then consider tightly limited live deployment."}],"analogy":"Risk management is the seat belt, brakes and guardrails of a car. A powerful engine is useless if the vehicle cannot stop safely.","mnemonic":"**S-A-F-E**: Size the risk, Add hard limits, Fail safely, Evaluate continuously.","example":"Illustrative research guardrails—not universal recommendations—might test 0.25% account risk per trade and a 1% daily stop. These are starting hypotheses for simulation, not promises of safety or personalised financial advice.","takeaways":["Risk limits and kill switches must be enforced in code.","ML must be validated against simple baselines and unseen data.","Keep credentials out of frontend code and GitHub.","Verify current Indian regulatory and broker requirements before live trading."]}', '[{"id":"d7q1","question":"A kill switch should:","options":["Increase position size after losses","Stop new trading when critical safety conditions fail","Disable logging","Hide broker rejections"],"answer":1,"explanation":"A kill switch prevents further exposure when system conditions are unsafe."},{"id":"d7q2","question":"Where should broker API secrets be stored?","options":["Public JavaScript file","GitHub repository","Secure server-side secret storage","HTML data attributes"],"answer":2,"explanation":"Secrets must never be exposed in browser code or public source control."},{"id":"d7q3","question":"Before live retail algo deployment in India, you should:","options":["Assume paper results are enough","Verify current SEBI, exchange and broker requirements","Skip broker approval","Use unlimited leverage"],"answer":1,"explanation":"Regulatory, exchange and broker requirements must be checked before live deployment."}]', 'scheduled');
